namespace Meziantou.Framework.JavaScriptEngine.Intl.Data;

/// <summary>
/// The CLDR data embedded in the engine (generated by tools/Meziantou.Framework.JavaScriptEngine.Data.Generator): the
/// locale data, the supplemental data and the collation data. Nothing is read before the first use, and each part is
/// decompressed by chunk on first use, so a script that does not use Intl pays nothing. The instances are thread-safe.
/// </summary>
internal sealed partial class CldrData
{
    private const string ResourcePrefix = "Meziantou.Framework.JavaScriptEngine.Intl.Data.";
    internal const string LocalesResourceName = ResourcePrefix + "locales.bin";
    internal const string SupplementalResourceName = ResourcePrefix + "supplemental.bin";
    internal const string CollationResourceName = ResourcePrefix + "collation.bin";

    private static CldrData? s_default;

    private readonly CldrChunkedFile _localesFile;
    private readonly CldrChunkedFile _supplementalFile;
    private readonly CldrChunkedFile _collationFile;
    private CldrLocaleData? _locales;
    private CldrSupplemental? _supplemental;
    private Collation.CollationData? _collation;

    internal CldrData(CldrChunkedFile locales, CldrChunkedFile supplemental, CldrChunkedFile collation)
    {
        _localesFile = locales;
        _supplementalFile = supplemental;
        _collationFile = collation;
    }

    /// <summary>Gets the data embedded in the engine.</summary>
    public static CldrData Default => Volatile.Read(ref s_default) ?? InitializeOnce(ref s_default, new CldrData(
        CldrChunkedFile.FromResource(LocalesResourceName),
        CldrChunkedFile.FromResource(SupplementalResourceName),
        CldrChunkedFile.FromResource(CollationResourceName)));

    public CldrLocaleData Locales => Volatile.Read(ref _locales) ?? InitializeOnce(ref _locales, new CldrLocaleData(_localesFile, () => Supplemental));

    public CldrSupplemental Supplemental => Volatile.Read(ref _supplemental) ?? InitializeOnce(ref _supplemental, new CldrSupplemental(_supplementalFile));

    public Collation.CollationData Collation => Volatile.Read(ref _collation) ?? InitializeOnce(ref _collation, new Collation.CollationData(_collationFile, () => Supplemental));

    internal CldrChunkedFile LocalesFile => _localesFile;

    internal CldrChunkedFile SupplementalFile => _supplementalFile;

    internal CldrChunkedFile CollationFile => _collationFile;

    /// <summary>Gets an available locale or alias by name (e.g. "fr-CA", "zh-TW"), ignoring the case, or null.</summary>
    public CldrLocale? GetLocale(string name) => Locales.TryGetLocale(name, out var locale) ? locale : null;

    /// <summary>Gets whether a locale is available (ECMA-402 [[AvailableLocales]]).</summary>
    public bool IsAvailableLocale(string name) => Locales.IsAvailableLocale(name);

    /// <summary>Finds the locale whose data to use for a language tag (its extensions are ignored), with fallback; the root when nothing matches.</summary>
    public CldrLocale FindLocale(string languageTag) => LanguageId.TryParse(languageTag, out var id) ? Locales.FindLocale(id) : Locales.Root;

    internal static T InitializeOnce<T>(ref T? field, T value)
        where T : class
    {
        return Interlocked.CompareExchange(ref field, value, comparand: null) ?? value;
    }
}
